-- Pakistan: milestones + English translations. Hand-written, following
-- the Indonesia pattern. Six milestones, live-researched against FBR's
-- own SRO PDFs (fbr.gov.pk / download1.fbr.gov.pk), EY/KPMG/PwC/Crowe tax
-- alerts, and Pakistani business press:
--
-- 1. pk-fmcg-pilot-2024 (2024-02-01, anchor, off-board, mandate_scope=
--    'b2b') -- SRO 28(I)/2024, the origin: FBR's first digital-invoicing
--    integration requirement, narrow FMCG-sector scope.
-- 2. pk-digital-invoicing-framework-2025 (2025-01-29, off-board,
--    mandate_scope='none') -- SRO 69(I)/2025 establishes the core
--    Chapter XIV technical/legal licensing-and-integration framework;
--    foundational/procedural, doesn't itself expand who must comply.
-- 3. pk-corporate-wave-2025 (2025-11-01, on-board, mandate_scope='b2b')
--    -- first major wave under SRO 1852(I)/2025's final schedule: public
--    companies, importers, turnover >Rs1bn, B2G suppliers.
-- 4. pk-full-rollout-2025 (2025-12-31, on-board, mandate_scope='b2b') --
--    all remaining registered persons go live, completing the formal
--    phased rollout -- the flagship/headline milestone. Description
--    includes the compliance-gap caveat: live adoption has lagged well
--    behind the legal deadline.
-- 5. pk-service-sector-draft-2026 (2026-02-18, on-board,
--    confidence='expected', mandate_scope='b2b') -- draft SRO 288(I)/2026,
--    a major proposed service-sector expansion. Description states
--    clearly this is a draft-for-comment, not yet a final enforceable
--    mandate.
-- 6. pk-finance-bill-enforcement-2026 (2026-06-12, on-board,
--    mandate_scope='none') -- Finance Bill 2026, penalty hardening and
--    enforcement infrastructure, not itself a scope expansion.
--
-- mandate_scope classification follows the exact values specified for
-- this migration rather than being independently derived -- see the
-- project brief's worked reasoning per milestone above.

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'pk-fmcg-pilot-2024', id, '2024-02-01', 1, 'https://download1.fbr.gov.pk/SROs/20241111215122200SRO28-2024.pdf', 0, '[]', NULL, 'b2b' FROM countries WHERE code = 'PK';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-fmcg-pilot-2024', 'en', 'SRO 28(I)/2024 launches FBR''s first digital-invoicing pilot, for the FMCG sector', 'On 1 February 2024, Pakistan''s Federal Board of Revenue (FBR) issued SRO 28(I)/2024, amending the Sales Tax Rules 2006 to require large fast-moving consumer goods (FMCG) manufacturers, importers, and distributors to issue electronic invoices integrated in real time with FBR''s systems. This was the origin of what has since grown into FBR''s economy-wide Digital Invoicing mandate, but at this stage the requirement applied only to a narrow, specific sector -- not the general registered-taxpayer population that later SROs would bring into scope.', '["No action required for this historical milestone -- included for context ahead of the entries below", "If you''re an FMCG manufacturer, importer, or distributor, confirm your digital-invoicing integration from this pilot phase is still functioning correctly under the current framework"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'pk-digital-invoicing-framework-2025', id, '2025-01-29', 0, 'https://download1.fbr.gov.pk/Docs/202541712407495sro69(I)2025.pdf', 0, '[]', NULL, 'none' FROM countries WHERE code = 'PK';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-digital-invoicing-framework-2025', 'en', 'SRO 69(I)/2025 establishes the core Chapter XIV licensing and integration framework', 'Issued 29 January 2025, SRO 69(I)/2025 built out Chapter XIV of the Sales Tax Rules 2006 into the technical and legal backbone of Pakistan''s digital-invoicing system: licensing rules for private integrators, the option to integrate via PRAL (Pakistan Revenue Automation Limited) at no cost, and the procedural detail behind real-time invoice submission and FBR validation. This SRO is foundational and procedural -- it built the machinery that later SROs would use to bring specific taxpayer populations into scope, but it did not itself expand who was legally required to issue digital invoices.', '["No action required for this historical milestone -- it establishes the technical/legal framework that later scope-expanding SROs (709, 1413, 1852) build on", "If you''re evaluating integration options, note this SRO is where the licensed-integrator and PRAL pathways were formally established"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'pk-corporate-wave-2025', id, '2025-11-01', 0, 'https://download1.fbr.gov.pk/SROs/2025924149054920SRO1852.pdf', 1, '[{"label": "FBR Digital Invoicing / IRIS", "url": "https://fbr.gov.pk/"}]', NULL, 'b2b' FROM countries WHERE code = 'PK';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-corporate-wave-2025', 'en', 'First wave of mandatory digital invoicing goes live under SRO 1852(I)/2025''s final schedule', 'From 1 November 2025, under SRO 1852(I)/2025''s controlling schedule (issued 24 September 2025, after SRO 709(I)/2025''s corporate/non-corporate expansion and two subsequent one-month deadline extensions, then SRO 1413(I)/2025''s turnover-tiered attempt), the first wave of registered persons became legally required to integrate with FBR''s Digital Invoicing system: public listed companies, importers, businesses with turnover above Rs 1 billion, and suppliers to government (B2G). Further waves under the same schedule followed on 15 November and 1 December 2025, ahead of the 31 December 2025 date that brings in everyone else.', '["If your business is a public company, an importer, has turnover above Rs 1 billion, or supplies government entities, confirm your FBR Digital Invoicing integration was live from this date", "Choose an integration path now -- direct API connection, a licensed integrator, or PRAL''s free option -- rather than waiting for a later wave''s deadline"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'pk-full-rollout-2025', id, '2025-12-31', 0, 'https://download1.fbr.gov.pk/SROs/2025924149054920SRO1852.pdf', 1, '[{"label": "FBR Digital Invoicing / IRIS", "url": "https://fbr.gov.pk/"}]', NULL, 'b2b' FROM countries WHERE code = 'PK';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-full-rollout-2025', 'en', 'All remaining registered persons must integrate -- the formal phased rollout completes', 'From 31 December 2025, SRO 1852(I)/2025''s final wave brought every remaining sales-tax-registered person into scope, completing on paper the phased rollout that began with SRO 28(I)/2024''s FMCG pilot nearly two years earlier. In practice, actual live compliance lagged badly behind this legal deadline: FBR''s own Member for Strategic Transformation stated that only around a third of registered taxpayers were issuing live digital invoices as of end-March 2026, and even on the older, narrower Tier-1 POS metric, 27-32% of the roughly 37,000 integrated retail branches remained disconnected as of June 2026. FBR only began serious enforcement -- importer penalty proceedings, registration suspension, customs green-channel removal -- from 1 July 2026, targeting full adoption by 31 July 2026. As of the most recent research (5 August 2026), there is no confirmation either way of whether that target was actually met -- treat this milestone as the legal completion of the mandate, not evidence that compliance is complete in practice.', '["Don''t assume the 31 December 2025 deadline means the mandate is settled in practice -- FBR''s own data shows real compliance is still catching up as of mid-2026", "If you haven''t yet integrated, treat FBR''s post-1-July-2026 enforcement push (penalty proceedings, registration suspension, green-channel removal) as active risk, not a future possibility"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'pk-service-sector-draft-2026', id, '2026-02-18', 0, 'https://download1.fbr.gov.pk/SROs/2026218112270512SRO288dated18.02.2026.pdf', 1, '[{"label": "FBR Digital Invoicing / IRIS", "url": "https://fbr.gov.pk/"}]', 'expected', 'b2b' FROM countries WHERE code = 'PK';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-service-sector-draft-2026', 'en', 'Draft SRO 288(I)/2026 proposes extending real-time invoicing to a broad new service-sector population', 'Published 18 February 2026 under Income Tax Rules Chapter VIIA, draft SRO 288(I)/2026 would extend real-time invoicing obligations to a wide new population of service-sector businesses -- restaurants, hospitals, salons, couriers, accountants, schools, gyms, and more. The primary FBR document confirms this was published as a draft for a 7-day public comment period, and it requires a further Income Tax General Order before it can actually take effect. Some Pakistani press coverage (Business Recorder, ProPakistani) described it in February 2026 as if it were already a binding mandate -- that framing gets ahead of the actual legal status. Treat this as a pending, expected expansion, not a confirmed one, until FBR publishes the follow-up General Order.', '["If your business falls into one of the newly-proposed categories (restaurant, hospital, salon, courier, accounting firm, school, gym, etc.), start preparing but don''t treat SRO 288(I)/2026 as already legally binding", "Watch for the follow-up Income Tax General Order that would actually bring this draft into force -- that''s the document to track, not the draft SRO itself"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'pk-finance-bill-enforcement-2026', id, '2026-06-12', 0, 'https://fbr.gov.pk/Budget2026-27/FinanceBill/Finance-Bill-2026.pdf', 1, '[{"label": "FBR Digital Invoicing / IRIS", "url": "https://fbr.gov.pk/"}]', NULL, 'none' FROM countries WHERE code = 'PK';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-finance-bill-enforcement-2026', 'en', 'Finance Bill 2026 hardens e-invoicing penalties and builds new enforcement infrastructure', 'Presented 12 June 2026 as part of an IMF-linked reform package, Finance Bill 2026 strengthens the penalty framework behind Pakistan''s digital-invoicing mandate rather than expanding who it covers: it establishes a National Faceless Centre to conduct electronic sales-tax audits, creates a public register naming issuers of fake or flying invoices, and extends e-invoicing obligations to excisable goods. This is enforcement-and-integrity infrastructure layered on top of the existing mandate''s scope, not a new population being brought into digital invoicing for the first time.', '["Review Finance Bill 2026''s penalty changes even if your business has already integrated -- the enforcement mechanisms (National Faceless Centre, fake-invoice register) apply on top of existing obligations", "If your business deals in excisable goods, confirm your digital-invoicing coverage now extends to those transactions"]');
